  4	import java.util.List;
  5	import java.util.Objects;
  6	
  7	public record PageResponse<T>(List<T> items, long total, int page, int size, int totalPages) {
  8	    public PageResponse {
  9	        items = List.copyOf(Objects.requireNonNull(items, "items"));
 10	        if (total < 0 || page < 0 || size < 1 || size > PageRequest.MAX_SIZE || totalPages < 0) {
 11	            throw new IllegalArgumentException("Invalid page metadata");
 12	        }
 13	        int expectedPages = total == 0 ? 0 : Math.toIntExact((total + size - 1) / size);
 14	        if (totalPages != expectedPages) throw new IllegalArgumentException("totalPages does not match total and size");
 15	        if (items.size() > size) throw new IllegalArgumentException("Page contains more items than size");
 16	    }
 17	
 18	    public static <T> PageResponse<T> of(List<T> items, long total, PageRequest request) {
 19	        int pages = total == 0 ? 0 : Math.toIntExact((total + request.size() - 1) / request.size());
 20	        return new PageResponse<>(items, total, request.page(), request.size(), pages);
 21	    }
 22	}
