  1	package com.papaya.claims.claim.domain;
  2	
  3	public record PageRequest(int page, int size) {
  4	    public static final int DEFAULT_PAGE = 0;
  5	    public static final int DEFAULT_SIZE = 20;
  6	    public static final int MAX_SIZE = 100;
  7	
  8	    public PageRequest {
  9	        if (page < 0) throw new IllegalArgumentException("page must be zero or greater");
 10	        if (size < 1 || size > MAX_SIZE) throw new IllegalArgumentException("size must be between 1 and " + MAX_SIZE);
 11	    }
 12	
 13	    public long offset() {
 14	        return Math.multiplyExact((long) page, size);
 15	    }
 16	}
