 11	class PageResponseTest {
 12	    @Test
 13	    void computesPageCountAndCopiesReturnedItems() {
 14	        var items = new ArrayList<>(List.of("a", "b"));
 15	        var page = PageResponse.of(items, 21, new PageRequest(1, 10));
 16	        items.add("outside");
 17	
 18	        assertThat(page.items()).containsExactly("a", "b");
 19	        assertThat(page.total()).isEqualTo(21);
 20	        assertThat(page.page()).isEqualTo(1);
 21	        assertThat(page.size()).isEqualTo(10);
 22	        assertThat(page.totalPages()).isEqualTo(3);
 23	    }
 24	
 25	    @Test
 26	    void emptyPageHasNoPagesAndRejectsInconsistentMetadata() {
 27	        assertThat(PageResponse.of(List.of(), 0, new PageRequest(0, 20)).totalPages()).isZero();
 28	        assertThatThrownBy(() -> new PageResponse<>(List.of(), 21, 0, 10, 1))
 29	                .isInstanceOf(IllegalArgumentException.class)
 30	                .hasMessage("totalPages does not match total and size");
 31	    }
 32	}
