 13	
 14	class DomainContractTest {
 15	    @Test
 16	    void factsDefensivelyCopyNestedJsonCollectionsAndPreserveDecimalPrecision() {
 17	        List<Object> nested = new ArrayList<>(List.of(new BigDecimal("0.10")));
 18	        Map<String, Object> input = new LinkedHashMap<>();
 19	        input.put("documents", nested);
 20	        ClaimFacts facts = new ClaimFacts(input);
 21	        nested.add("late mutation");
 22	        input.put("new", true);
 23	
 24	        assertThat(facts.values()).containsOnlyKeys("documents");
 25	        assertThat(facts.values().get("documents")).isEqualTo(List.of(new BigDecimal("0.10")));
 26	        assertThatThrownBy(() -> facts.values().put("x", true)).isInstanceOf(UnsupportedOperationException.class);
 27	        assertThatThrownBy(() -> ((List<?>) facts.values().get("documents")).clear())
 28	                .isInstanceOf(UnsupportedOperationException.class);
 29	    }
 30	
 31	    @Test
 32	    void actorCopiesRolesAndRequiresProtectedSystemRole() {
 33	        var roles = new java.util.HashSet<>(Set.of("assessor"));
 34	        Actor actor = new Actor("u-1", roles, false);
 35	        roles.add("finance");
 36	        assertThat(actor.roles()).containsExactly("assessor");
 37	        assertThatThrownBy(() -> new Actor("system-job", Set.of(), true))
 38	                .isInstanceOf(IllegalArgumentException.class)
 39	                .hasMessage("System actor must hold the protected system role");
 40	    }
 41	
 42	    @Test
 43	    void pageBoundsAndOverflowAreExplicit() {
